/** Sequential two-connection snapshot/lease contract with root-run borrowing enabled by default. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeRootRunSnapshotTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:packed:rhs:snapshot:";
	private static final int LANES = 4096;
	private static final String[] ON = { "rdf4j.lmdb.nativeQueryEngine.enabled", "rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.packedFtree.algebra.enabled", "rdf4j.lmdb.factor.transport.enabled",
			"rdf4j.lmdb.janinoCodegen.factorMarginals",
			LmdbDirectAdjacencyStore.CLEAN_TXN_READS_PROPERTY };
	private static final String[] OFF = { "rdf4j.lmdb.costCalibration.enabled", "rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.packedFtree.parallel.enabled", "rdf4j.lmdb.janinoCodegen.enabled" };
	private static final String QUERY = query();
	private final Map<String, String> previous = new HashMap<>();
	@TempDir
	File directory;
	private SailRepository repository;
	private LmdbStore store;
	private LmdbDirectAdjacencyStore direct;

	@BeforeEach
	void setUp() throws Exception {
		String rootProperty = "rdf4j.lmdb.packedFtree.rootFactor.enabled";
		previous.put(rootProperty, System.getProperty(rootProperty));
		System.clearProperty(rootProperty);
		for (String property : ON)
			setProperty(property, "true");
		for (String property : OFF)
			setProperty(property, "false");
		store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setValueOverlayEnabled(false)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repository = new SailRepository(store);
		repository.init();
		try (SailRepositoryConnection writer = repository.getConnection()) {
			writer.begin();
			addChain(writer, "s", "o0", "v0");
			addChain(writer, "s", "o1", "v1");
			writer.add(iri("missing"), RDF.TYPE, iri("Marker"));
			for (int lane = 0; lane < LANES; lane++)
				writer.add(iri("lane" + lane), iri("laneValue"), integer(lane));
			writer.commit();
		}
		assertTrue(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS));
		direct = store.getBackingStore().directAdjacencyStore();
		assertNotNull(direct);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = prepare(connection).explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertTrue(hasPackedPath(plan), () -> "fixture must actually execute packedFtree: " + plan);
		}
		assertEquals(0L, direct.snapshotMetrics().activeViews);
	}

	@AfterEach
	void tearDown() {
		try {
			if (repository != null)
				repository.shutDown();
		} finally {
			previous.forEach((property, value) -> {
				if (value == null)
					System.clearProperty(property);
				else
					System.setProperty(property, value);
			});
		}
	}

	@Test
	void activeResultKeepsOldSnapshotAfterAnotherConnectionCommits() throws Exception {
		Map<String, Long> oldBag = new HashMap<>();
		try (SailRepositoryConnection reader = repository.getConnection()) {
			reader.begin(IsolationLevels.SNAPSHOT_READ);
			try (TupleQueryResult old = prepare(reader).evaluate()) {
				assertTrue(old.hasNext());
				add(oldBag, old.next());
				assertTrue(direct.snapshotMetrics().activeViews > 0,
						"fixture must retain an adjacency lease while old result is active");
				try (SailRepositoryConnection writer = repository.getConnection()) {
					writer.begin();
					writer.remove(iri("s"), iri("p"), iri("o0"));
					addChain(writer, "s", "o2", "v2");
					addChain(writer, "missing", "m", "mv");
					writer.commit();
				}
				// No threads: the active query must keep its old snapshot across a sequential later commit.
				while (old.hasNext())
					add(oldBag, old.next());
			}
			assertEquals(expected(false), oldBag);
			reader.rollback();
		}
		assertEquals(0L, direct.snapshotMetrics().activeViews, "old query and transaction must release leases");
		assertTrue(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS));
		try (SailRepositoryConnection fresh = repository.getConnection()) {
			assertEquals(expected(true), collect(prepare(fresh).evaluate()));
		}
		assertEquals(0L, direct.snapshotMetrics().activeViews);
	}

	@Test
	void earlyCloseReleasesQueryLeaseBeforeConnectionCloses() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			try (TupleQueryResult rows = prepare(connection).evaluate()) {
				assertTrue(rows.hasNext());
				rows.next();
				assertTrue(direct.snapshotMetrics().activeViews > 0);
			}
			assertEquals(0L, direct.snapshotMetrics().activeViews,
					"closing the result, not merely the connection, must release the retained runtime lease");
			assertEquals(expected(false), collect(prepare(connection).evaluate()));
		}
		assertEquals(0L, direct.snapshotMetrics().activeViews);
	}

	private void setProperty(String property, String value) {
		previous.put(property, System.getProperty(property));
		System.setProperty(property, value);
	}

	private static String query() {
		StringBuilder query = new StringBuilder("PREFIX ex: <" + NS
				+ "> SELECT ?lane ?s ?o WHERE { VALUES (?lane ?s) { ");
		for (int lane = 0; lane < LANES; lane++)
			query.append('(').append(lane).append(lane < LANES - 16 ? " ex:s) " : " ex:missing) ");
		return query.append("} OPTIONAL { ?s ex:p ?o . } }").toString();
	}

	private static SailTupleQuery prepare(SailRepositoryConnection connection) {
		SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(QUERY);
		query.setIncludeInferred(false);
		query.setMaxExecutionTime(60);
		query.setForcedLmdbExecutionStrategy("packedFtree");
		return query;
	}

	private static boolean hasPackedPath(GenericPlanNode node) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null && Arrays.asList(path.split("\\|")).contains("packedFtree"))
			return true;
		return node.getPlans() != null
				&& node.getPlans().stream().anyMatch(LmdbNativeRootRunSnapshotTest::hasPackedPath);
	}

	private static Map<String, Long> collect(TupleQueryResult result) {
		Map<String, Long> bag = new HashMap<>();
		try (result) {
			while (result.hasNext())
				add(bag, result.next());
		}
		return bag;
	}

	private static void add(Map<String, Long> bag, BindingSet bindings) {
		Map<String, Value> values = new TreeMap<>();
		bindings.forEach(binding -> values.put(binding.getName(), binding.getValue()));
		bag.merge(values.toString(), 1L, Long::sum);
	}

	private static Map<String, Long> expected(boolean updated) {
		Map<String, Long> bag = new HashMap<>();
		for (int lane = 0; lane < LANES; lane++) {
			if (lane >= LANES - 16) {
				Map<String, Value> row = new TreeMap<>(Map.of("lane", integer(lane), "s", iri("missing")));
				if (updated) {
					row.put("o", iri("m"));
				}
				bag.put(row.toString(), 1L);
			} else {
				for (int edge : updated ? new int[] { 1, 2 } : new int[] { 0, 1 }) {
					bag.put(new TreeMap<>(Map.of("lane", integer(lane), "s", iri("s"),
							"o", iri("o" + edge))).toString(), 1L);
				}
			}
		}
		return bag;
	}

	private static void addChain(SailRepositoryConnection writer, String subject, String object, String value) {
		writer.add(iri(subject), iri("p"), iri(object));
		writer.add(iri(object), iri("q"), iri(value));
	}

	private static Value integer(int value) {
		return VF.createLiteral(BigInteger.valueOf(value));
	}

	private static IRI iri(String local) {
		return VF.createIRI(NS, local);
	}
}
